"use client";

import { useRef, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import {
  useMotionTemplate,
  useMotionValueEvent,
  useScroll,
  useTransform,
  type MotionValue,
} from "motion/react";
import { PinwheelMark } from "@/components/brand/PinwheelMark";
import { HashLink } from "@/components/ui/HashLink";
import { PETALS, STEP } from "@/lib/data/petals";
import { PILLARS } from "@/lib/data/pillars";
import { SERVICES, servicesIn } from "@/lib/data/services";
import { useMotionStyles } from "@/lib/use-motion-styles";

/*
 * THE OPENING SEQUENCE - one pinned stage, one scroll timeline.
 *
 * Act 1  "From Concept to Celebration: Unforgettable Experiences" opens as
 *        OUTLINE type - drawn but not yet made, which is what concept looks
 *        like. Five threads, one per figure in the logo, sweep across and
 *        leave the words SOLID behind them: the headline is built by the
 *        brand palette. The threads gather, resolve into the mark, and the
 *        mark floods the screen.
 * Act 2  "Five disciplines. One team on the floor." rises out of the flood
 *        and anchors to the top of the stage.
 * Act 3  The mark returns hollow. The wheel turns one petal per beat; each
 *        turn claims a figure in its real logo colour and names the
 *        discipline it stands for. After five turns it has come full circle
 *        and the logo is whole.
 *
 * WHY ONE COMPONENT AND NOT TWO. This was first built as a Threads hero
 * followed by a separate pinned Petals section, and that is structurally
 * incapable of working: two sticky stages means the first one is scrolling
 * out of the top of the viewport while the second scrolls in from the
 * bottom, so for a full screen-height the handover line is visible TWICE,
 * once near each edge. Matching the two copies pixel for pixel does not
 * help - the duplication is the sticky mechanics, not the styling. One
 * wrapper, one sticky child and one progress value means the line is a
 * single element that simply moves.
 *
 * WHY EVERY SCROLL-LINKED STYLE GOES THROUGH useMotionStyles. Binding a
 * useScroll-derived MotionValue to a motion component's style prop makes
 * Motion hand the animation to a native CSS ViewTimeline, whose progress
 * is a different curve from useScroll's offset. The paint then silently
 * desyncs from the value. See the note in use-motion-styles.ts.
 *
 * NOTHING HERE HARDCODES A THEME. An earlier pass forced Act 3 onto a dark
 * stage to rescue the amber figure (#fcd088 is only about 1.3:1 on the bone
 * page). That is now the theme system's job: the petal tokens resolve to the
 * authored artwork colours in dark and to lightness-corrected ones in light,
 * so this component just uses surface / ink / hairline and follows whichever
 * theme the visitor chose. See tokens.css.
 *
 * REDUCED MOTION is handled in CSS, never by returning a different tree.
 * useReducedMotion() is false during SSR, so branching on it renders one
 * structure on the server and another on the client - that produced a real
 * hydration mismatch plus Motion's "Target ref is defined but not
 * hydrated" error. The markup below is identical in both modes.
 */

const THREADS = [
  { key: "activation", color: "var(--color-activation-mark)", y: -0.34, len: 0.16, lag: 0.0 },
  { key: "content", color: "var(--color-content-mark)", y: -0.14, len: 0.26, lag: 0.03 },
  { key: "live", color: "var(--color-live-mark)", y: 0.06, len: 0.2, lag: 0.06 },
  { key: "corporate", color: "var(--color-corporate-mark)", y: 0.26, len: 0.3, lag: 0.09 },
  { key: "weddings", color: "var(--color-weddings-mark)", y: 0.46, len: 0.14, lag: 0.12 },
];

const HEADLINE_STYLE = {
  fontFamily: "var(--font-display)",
  fontWeight: 800,
  fontSize: "clamp(2.25rem, 0.9rem + 5.4vw, 5.5rem)",
  lineHeight: 1.02,
  letterSpacing: "-0.035em",
} as const;

/*
 * How far the solid layer's clip-path reaches PAST its own box, top and
 * bottom, as a percentage of that box.
 *
 * Without it the descenders never fill in. clip-path clips to the border
 * box, and lineHeight 1.02 above means the line box is barely taller than
 * the em - so Manrope's descenders paint below it. Measured at the 88px
 * cap: the h1 box ends at y=570 and the glyph run ends at y=584, i.e. 14px
 * of every g, p and y hanging outside. The outline layer has no clip-path
 * so it kept its descenders, the solid layer lost them, and the result was
 * a headline that filled in white except for the tails, which stayed as
 * hollow outlines for the whole sequence.
 *
 * Percent, not px, because the font-size is a clamp() - the overhang
 * scales with it, so a fixed pixel figure would be right at exactly one
 * viewport width. 25 is far more than the ~8% measured; there is nothing
 * else inside this layer, so over-reaching reveals nothing and costs
 * nothing. Negative inset() offsets are what expand a clip region outward
 * (verified supported before relying on it).
 */
const CLIP_BLEED = 25;

const ANCHOR_STYLE = {
  fontFamily: "var(--font-display)",
  fontWeight: 800,
  fontSize: "clamp(1.75rem, 1rem + 3vw, 3rem)",
  lineHeight: 1.02,
  letterSpacing: "-0.035em",
} as const;

/*
 * Beat 1 reveals the wheel; 1-5 are the petals; 6 is the close.
 *
 * WHAT ONE BEAT COSTS IN SCROLL - the number a visitor actually feels,
 * and one that is invisible from this array on its own. useScroll with
 * ["start start", "end end"] runs p from 0 to 1 over the wrapper's height
 * MINUS one viewport, so the whole sequence is (wrapper - 100)svh of
 * travel and a single beat is its gap here multiplied by that.
 *
 * At the 980svh this wrapper started at, that travel was 880svh, and the
 * ~0.095 between beats put one petal turn at ~84svh - about 750px on a
 * 900px-tall window, which is seven or eight wheel notches, or two to
 * three trackpad flicks, PER PETAL. Five petals of that does not read as
 * a slow sequence, it reads as the page having stopped responding.
 *
 * A first pass at 560svh was measured in the browser at 373px per beat.
 * That is under four notches of a 100px wheel - but a high-resolution
 * wheel steps about 190px, which put it at almost exactly two, and two
 * was still the complaint. Hence 420svh: travel 320svh, a beat ~29svh, or
 * 259px at a 900px window. Act 1 comes down with it - the headline wipe
 * (p 0.04 -> 0.25) was 185svh at the original 980, and is now ~67svh.
 *
 * HEIGHT IS ONLY HALF OF IT. The other half is how long the wheel takes
 * to turn once a beat fires, which no wrapper height can reach - see the
 * duration note on PinwheelMark below. Changing one without the other is
 * why the first attempt at this landed short.
 *
 * IF THE PACE NEEDS CHANGING AGAIN, CHANGE THOSE TWO, NOT THESE.
 * The fractions are the RHYTHM between the acts and are tuned against
 * each other and against a dozen useTransform ranges below; the height is
 * the SPEED, and it is the only knob here that can be turned on its own.
 */
const BEAT_AT = [0.47, 0.57, 0.66, 0.75, 0.84, 0.93];

const DISCIPLINES = PETALS.map((petal, i) => {
  const pillar = PILLARS.find((p) => p.id === petal.id)!;
  return {
    ...petal,
    index: String(i + 1).padStart(2, "0"),
    name: pillar.name,
    blurb: pillar.blurb,
    // A capability can be sold under several petals, so the same pill
    // appears on more than one beat - see the note at the top of
    // services.ts. The pills wrap, so a longer list costs height, not
    // layout.
    services: servicesIn(petal.id),
  };
});

export function HeroSequence() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress: p } = useScroll({
    target: wrapRef,
    offset: ["start start", "end end"],
  });

  // ---- Act 1 ----------------------------------------------------------
  const wipeRight = useTransform(p, [0.04, 0.25], [100, 0]);
  const clip = useMotionTemplate`inset(${-CLIP_BLEED}% ${wipeRight}% ${-CLIP_BLEED}% 0)`;
  const front = useTransform(p, [0.04, 0.25], [0, 100]);
  const gather = useTransform(p, [0.25, 0.31], [0, 1]);
  const threadOpacity = useTransform(p, [0.02, 0.05, 0.29, 0.33], [0, 1, 1, 0]);
  const uiOpacity = useTransform(p, [0, 0.04, 0.08], [1, 1, 0]);
  const headlineOpacity = useTransform(p, [0.29, 0.34], [1, 0]);
  const markOpacity = useTransform(p, [0.28, 0.31, 0.36, 0.39], [0, 1, 1, 0]);
  const markTransform = useTransform(
    useTransform(p, [0.29, 0.38], [0.35, 16]),
    (s) => `scale(${s})`,
  );
  // The flood carries the hand-off from Act 1 to Act 2 and is then CLEARED
  // before the wheel arrives. Leaving it up looked fine but is a real
  // contrast trap: the tint sits between the text and the page, and the
  // petal tokens were solved against the plain surface, not against a
  // purple wash. Measured over the flood, three petals dropped to 2.74-2.76:1
  // in light and the purple to 2.81:1 in dark - all under the 3:1 they are
  // supposed to hold. On the bare surface they are 3.01-13.01:1.
  const floodOpacity = useTransform(p, [0.32, 0.38, 0.47, 0.53], [0, 1, 1, 0]);

  // ---- Act 2: the line rises out of the flood and anchors -------------
  const lineOpacity = useTransform(p, [0.37, 0.42], [0, 1]);
  // 1 = parked at centre, 0 = anchored at top. Scroll-linked rather than a
  // CSS transition so the move tracks the scroll instead of firing once.
  // 0.51em is half a line box at line-height 1.02 - using em rather than
  // 50% keeps the multiplication inside calc() unambiguous.
  const park = useTransform(p, [0.42, 0.5], [1, 0]);
  const lineTransform = useMotionTemplate`translateY(calc(${park} * (42svh - 0.51em)))`;

  // ---- Act 3 ----------------------------------------------------------
  const [beat, setBeat] = useState(0);
  useMotionValueEvent(p, "change", (v) => {
    let next = 0;
    for (const t of BEAT_AT) if (v >= t) next += 1;
    setBeat(next);
  });

  const entered = beat >= 1;
  const active = beat >= 1 && beat <= 5 ? DISCIPLINES[beat - 1] : null;
  const rotation = beat <= 1 ? 0 : -STEP * (beat - 1);
  const filled = DISCIPLINES.slice(0, Math.min(beat, 5)).map((d) => d.id);

  const hue = useTransform(p, [0.04, 0.1, 0.16, 0.22, 0.28], [26, 79, 146, 220, 314]);
  useMotionValueEvent(hue, "change", (h) => {
    document.documentElement.style.setProperty("--brand-hue", String(h));
  });

  /*
   * THE HAND-OFF. Everything above solves the sequence while it is PINNED;
   * this is the only thing that deals with it ending, and without it the
   * close is guillotined on the way out.
   *
   * .hero-stage reserves --header-h so the stage and the sticky Header
   * never share pixels - but that reservation only holds while the stage
   * is stuck. The instant p passes 1 the pin releases and the stage
   * scrolls up like any ordinary block, straight behind a header that is
   * still stuck at top-0. What that looks like was measured at 1536x744,
   * ~200px past the end: the mark sliced clean across the middle of its
   * top petal by the header edge, with the closing headline crammed into
   * the strip underneath. It reads as a broken layout rather than as a
   * section leaving, because a composed full-height frame with a 400px
   * graphic in it is not what a header is normally asked to scroll over.
   *
   * The same window is where the Trusted by card arrives. It sits at
   * -mt-16, so it laps 64px over the end of this wrapper - and the beat
   * dots are pinned bottom-6, i.e. 24px up. Measured at both 1440x900 and
   * 1536x744: the card covers the entire dot rail. Two independently
   * chosen numbers that happen to cancel.
   *
   * Fading the layer out fixes both at once - there is nothing left to
   * slice and nothing left under the card - but it CANNOT be driven by p.
   *
   * That was the first attempt and it is worth recording why it was
   * wrong, because the fix looks correct until you stop scrolling in the
   * wrong place. p is clamped to 1, and 1 is reached while the stage is
   * still fully pinned and on screen - so a fade ending at p=1 has to run
   * during the last stretch of BEAT 6, the one frame carrying "View All
   * Services" and "Start an Enquiry". Measured at 420svh, beat 6 owns
   * p 0.93 -> 1, which is 167px of scroll; fading across the back half of
   * that left a reader who stopped at the end of the sequence looking at
   * the close at under 30% opacity, with both CTAs nearly invisible. It
   * removed the slice by deleting the ending.
   *
   * A SECOND useScroll, scoped to the exit, is what the timeline actually
   * needs. ["end end", "end start"] runs 0 -> 1 as the wrapper's bottom
   * edge travels from the bottom of the viewport to the top - which is
   * exactly the window the pin has released into, and is one viewport
   * tall. So the close holds at full strength right through p=1 and only
   * then begins to go.
   *
   * 0.18 of that window is ~134px at a 744px viewport, and it is measured
   * against the thing being protected rather than picked: the mark sits
   * ~154px below the stage top, so the header edge first touches it at
   * 0.21 of the exit. Finishing at 0.18 means the graphic is already gone
   * before anything can cut it. The anchored line above it does pass the
   * header while still faintly visible - unavoidable, it starts ~60px
   * from the stage top - but a fading line slipping behind a header reads
   * as leaving, which is what it is doing.
   */
  const { scrollYProgress: exit } = useScroll({
    target: wrapRef,
    offset: ["end end", "end start"],
  });
  /* The 0.04 lead-in is not a rounding fudge, it is the Header's own
     height animation. It shrinks 110px -> 84px on scroll, which moves
     every offset below it while this window is being measured - enough
     that the close was reading 0.8 opacity at the exact moment the pin
     released. The dead zone lets the ending land at full strength and
     still finishes before 0.21, where the header edge reaches the mark. */
  const handoff = useTransform(exit, [0.04, 0.2], [1, 0]);

  const eyebrowRef = useRef<HTMLParagraphElement>(null);
  const headlineRef = useRef<HTMLDivElement>(null);
  const solidRef = useRef<HTMLDivElement>(null);
  const threadsRef = useRef<HTMLDivElement>(null);
  const ctaRef = useRef<HTMLDivElement>(null);
  const markRef = useRef<HTMLDivElement>(null);
  const floodRef = useRef<HTMLDivElement>(null);
  const lineRef = useRef<HTMLHeadingElement>(null);
  const actsRef = useRef<HTMLDivElement>(null);

  useMotionStyles(eyebrowRef, { opacity: uiOpacity });
  useMotionStyles(headlineRef, { opacity: headlineOpacity });
  useMotionStyles(solidRef, { "clip-path": clip });
  useMotionStyles(threadsRef, { opacity: threadOpacity });
  useMotionStyles(ctaRef, { opacity: uiOpacity });
  useMotionStyles(markRef, { opacity: markOpacity, transform: markTransform });
  useMotionStyles(floodRef, { opacity: floodOpacity });
  useMotionStyles(lineRef, { opacity: lineOpacity, transform: lineTransform });
  useMotionStyles(actsRef, { opacity: handoff });

  return (
    // HALF OF HOW FAST THIS SEQUENCE FEELS IS THIS ONE NUMBER; the other
    // half is the PinwheelMark duration further down, and neither alone
    // is enough. See BEAT_AT for the arithmetic that turns a wrapper
    // height into "how much scroll is one beat", and change it there
    // rather than moving the beats.
    <div ref={wrapRef} className="relative h-[420svh] motion-reduce:h-auto">
      {/* .hero-stage (globals.css): reserves Header's real height via
          --header-h so the two sticky elements never overlap while the
          stage is PINNED. The hand-off out of the pin is a separate
          problem with a separate fix - see `handoff` above. */}
      <div className="hero-stage">
        {/* ---- backdrop stack ---- */}
        <div
          ref={floodRef}
          aria-hidden="true"
          className="absolute inset-0 motion-reduce:hidden"
          style={{
            opacity: 0,
            background:
              "radial-gradient(120% 120% at 50% 50%, var(--flood-inner) 0%, var(--flood-outer) 100%)",
          }}
        />

        {/* ---- ACT 1 ---- */}
        <div className="absolute inset-0 flex items-center motion-reduce:static motion-reduce:min-h-svh motion-reduce:py-24">
          <div className="relative mx-auto w-full max-w-[1440px] px-6 lg:px-10">
            <p
              ref={eyebrowRef}
              className="text-eyebrow mb-6 uppercase text-ink-muted motion-reduce:!opacity-100"
            >
              We create experiences
            </p>

            <div ref={headlineRef} className="relative motion-reduce:!opacity-100">
              {/* Outline layer - the real, accessible headline. */}
              <h1
                className="relative"
                style={{
                  ...HEADLINE_STYLE,
                  WebkitTextStroke: "1.25px var(--color-ink)",
                  color: "transparent",
                }}
              >
                From Concept to Celebration:
                <br />
                Unforgettable Experiences
              </h1>

              {/* Solid layer, revealed by the wipe. */}
              <div
                ref={solidRef}
                aria-hidden="true"
                // Both clip values carry the vertical bleed too - the
                // reduced-motion one because it is the FINAL state (fully
                // wiped), which is exactly where a clipped descender would
                // sit permanently, and the inline one because it is what
                // the server renders before any scroll value exists.
                className="absolute inset-0 text-ink motion-reduce:![clip-path:inset(-25%_0_-25%_0)]"
                style={{ ...HEADLINE_STYLE, clipPath: `inset(${-CLIP_BLEED}% 100% ${-CLIP_BLEED}% 0)` }}
              >
                From Concept to Celebration:
                <br />
                Unforgettable Experiences
              </div>

              <div
                ref={threadsRef}
                aria-hidden="true"
                className="pointer-events-none absolute inset-0 motion-reduce:hidden"
                style={{ opacity: 0 }}
              >
                {THREADS.map((t) => (
                  <Thread key={t.key} thread={t} front={front} gather={gather} />
                ))}
              </div>
            </div>

            {/* Reduced motion never sees the sweep, so state the palette. */}
            <div className="mt-8 hidden gap-2 motion-reduce:flex" aria-hidden="true">
              {THREADS.map((t) => (
                <span
                  key={t.key}
                  className="h-[5px] w-16 rounded-full"
                  style={{ background: t.color }}
                />
              ))}
            </div>

            <div
              ref={ctaRef}
              className="mt-10 flex flex-wrap gap-4 motion-reduce:!opacity-100"
            >
              {/* Was /work, which has never been built and 404d. The
                  carousel further down this page is the whole of WORK
                  rather than a selection from it, so there is nothing a
                  separate archive page would add - id on the section in
                  CaseStudies.tsx. */}
              {/*
               * HashLink, NOT Link, AND THAT IS THE WHOLE FIX FOR A
               * REPORTED BUG: this button worked exactly once. next/link
               * no-ops a click whose URL matches the current one, so once
               * the first click had put /#work in the address bar, every
               * later click did nothing - and a reader who scrolls back up
               * to the hero is exactly the person who clicks it again.
               * Measured from the same scrollY of 0: 7975 with the fix, 0
               * without. Full reasoning in HashLink.tsx.
               */}
              <HashLink
                href="/#work"
                className="rounded-md bg-corporate-fill px-6 py-3 font-medium text-white transition-colors duration-[var(--dur-fast)] hover:bg-corporate-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-corporate-ink"
              >
                Explore Our Work
              </HashLink>
              {/* Was /about, now the About section further down this same
                  page - there is no separate About page and never was.
                  Sits directly above that section, so this is a short
                  jump rather than a navigation. HashLink for the reason
                  spelled out on "Explore Our Work" above. */}
              <HashLink
                href="/#about"
                className="rounded-md border border-hairline px-6 py-3 font-medium text-ink transition-colors duration-[var(--dur-fast)] hover:border-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-corporate-ink"
              >
                Know More About Us
              </HashLink>
            </div>
          </div>
        </div>

        {/* Threads resolve into the mark, the mark floods the screen. */}
        <div
          ref={markRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 flex items-center justify-center motion-reduce:hidden"
          style={{ opacity: 0 }}
        >
          <Image
            src="/logo-mark.png"
            alt=""
            width={729}
            height={710}
            className="h-[22vmin] w-auto"
          />
        </div>

        {/* ---- ACTS 2 + 3 ---- */}
        {/*
         * pointer-events follows `entered`, and that is a bug fix, not a
         * nicety. This layer is absolute inset-0 and comes AFTER Act 1
         * in the DOM, so it paints on top of Act 1's two CTAs. Its panel
         * is faded with opacity, and opacity: 0 hides an element from
         * the eye but NOT from hit-testing - so before the first beat
         * this invisible layer sat over "Explore Our Work" and "Know
         * More About Us" and swallowed every click on them. Both buttons
         * looked completely dead; elementFromPoint at their centres
         * returned the pinwheel SVG in here rather than the links.
         *
         * The motion-reduce override is the trap in the fix. Under
         * reduced motion the sequence never runs, so `entered` stays
         * false forever while these acts are laid out statically and
         * forced visible by motion-reduce:!opacity-100 below. Without
         * the override, the fix would leave this layer's own links -
         * the five disciplines, /services and /#enquiry - permanently
         * unclickable for exactly the users least able to work around
         * it.
         */}
        {/* motion-reduce:!opacity-100 is load-bearing, not tidiness. Under
            reduced motion the timeline never advances, so `handoff` sits
            at its p=0 value forever - which is 1 here, but only by luck of
            the range direction. The override makes the static layout
            independent of that, the same guard Stratum carries in
            AboutPortal.tsx and for the same reason: an important rule in a
            stylesheet outranks the non-important inline style
            useMotionStyles writes. */}
        <div
          ref={actsRef}
          className={`absolute inset-0 flex flex-col px-6 lg:px-10 motion-reduce:static motion-reduce:!pointer-events-auto motion-reduce:!opacity-100 motion-reduce:py-24 ${
            entered ? "" : "pointer-events-none"
          }`}
        >
          <div className="mx-auto flex h-full w-full max-w-[1440px] flex-col">
            {/*
              ---- THE MOBILE VERTICAL BUDGET ----
              (this block, the gap/padding below, and the mark's width)

              .hero-stage is 100svh - --header-h and it clips, and below md
              this act is ONE COLUMN: anchored line, then the mark, then a
              discipline's number, name, blurb and up to eight capability
              pills. Stacked, that wants more than the stage has. Measured
              at 360x667 before these: the last pill of Corporate & MICE -
              the widest list - sat 85.6px BELOW the stage floor, so the
              bottom row of pills was simply gone and the beat dots were
              painting over the row above it.

              svh sizing does not save this on its own. On a real phone
              100svh is the viewport with the browser chrome SHOWING, which
              is well short of the window: an iPhone 14 reports 844 to a
              desktop emulator but about 745svh in Safari, so the stage a
              visitor actually gets is ~58px tighter than anything measured
              on a desktop at the same nominal size. These steps down are
              sized against that, not against the emulator.

              At md the two-column grid puts the mark beside the copy
              instead of above it and the pressure disappears, so every
              original value returns there untouched.
            */}
            <div className="pt-[4svh] motion-reduce:pt-0 md:pt-[8svh]">
              {/* ONE instance of this line for the whole sequence. */}
              <h2
                ref={lineRef}
                className="text-center text-ink motion-reduce:!opacity-100 motion-reduce:!transform-none"
                style={{ ...ANCHOR_STYLE, opacity: 0 }}
              >
                Five disciplines. One team on the floor.
              </h2>
            </div>

            <div
              className="grid flex-1 items-center gap-5 pb-[3svh] transition-opacity duration-[900ms] motion-reduce:!opacity-100 md:grid-cols-[minmax(0,42%)_minmax(0,1fr)] md:gap-14 md:pb-[8svh]"
              style={{ opacity: entered ? 1 : 0 }}
            >
              {/* 34vw, not 46, and it is the single biggest line in the
                  budget above: at 360px that is 122px of mark instead of
                  166px. The wheel is the one element here that can give up
                  height without giving up meaning - it is decorative, it
                  already had a full act of its own at Act 1, and it is
                  still the largest thing on the screen at this size. */}
              <div className="relative mx-auto w-[min(34vw,300px)] md:w-full md:max-w-[420px]">
                {/*
                  duration IS PART OF HOW FAST THIS SEQUENCE FEELS, and it
                  is the half that shortening the wrapper cannot reach.

                  The beat threshold fires the instant scroll crosses it,
                  but the petal then takes this long to actually arrive,
                  on an expo ease that spends most of its time settling.
                  At the 0.9s default that is comfortably longer than the
                  scroll it takes to cross a whole beat - so a reader
                  nudges the wheel, sees almost nothing move, nudges again,
                  and has now crossed two thresholds while watching one
                  slow turn. It reads as "two scrolls per rotation" no
                  matter how short the wrapper gets, which is exactly why
                  the first pass at this - height alone - did not fix it.

                  0.45 lands the turn inside a single beat's worth of
                  scroll. Not lower: the rotation is the one thing on
                  screen actually reporting that a beat happened, and a
                  snap would lose the sense of the wheel being turned.
                */}
                <PinwheelMark
                  rotation={rotation}
                  filled={filled}
                  duration={0.45}
                  className="h-auto w-full"
                />
              </div>

              {/*
                EVERY PANEL IS ALWAYS IN FLOW, STACKED IN ONE GRID CELL.
                They used to switch with display:none, which is why the
                copy changed with a hard cut however long the transition
                said it was: a transition has nothing to run FROM out of
                display:none, and the outgoing panel was pulled the instant
                the beat changed, so its fade never got a frame.

                Grid stacking rather than absolute positioning because the
                cell then sizes to the TALLEST discipline instead of the
                current one - the blurbs and chip counts differ enough that
                the old version also nudged its own height on every beat.
              */}
              <div className="grid min-h-[clamp(240px,34svh,340px)]">
                {DISCIPLINES.map((d, i) => {
                  const isActive = active?.id === d.id;
                  return (
                    <div
                      key={d.id}
                      aria-hidden={!isActive}
                      className="col-start-1 row-start-1 transition-[opacity,transform] ease-out-expo"
                      style={{
                        opacity: isActive ? 1 : 0,
                        /* Signed against the beat, so a discipline already
                           passed leaves upward and one still to come waits
                           below - the copy travels the same way the wheel
                           is turning, and reverses with it on scroll-up. */
                        transform: isActive
                          ? "none"
                          : `translateY(${i < beat - 1 ? -18 : 18}px)`,
                        /* Out faster than in, and in slightly behind, so
                           the two never sit at half opacity on top of each
                           other. */
                        transitionDuration: isActive ? "620ms" : "360ms",
                        transitionDelay: isActive ? "110ms" : "0ms",
                        // They overlap now, so only the live one is hittable.
                        pointerEvents: isActive ? "auto" : "none",
                      }}
                    >
                      <span
                        className="tabular-nums"
                        style={{
                          color: d.color,
                          fontFamily: "var(--font-display)",
                          fontWeight: 800,
                          fontSize: "clamp(2.5rem, 1.6rem + 3vw, 4rem)",
                          letterSpacing: "-0.03em",
                          lineHeight: 1,
                        }}
                      >
                        {d.index}
                      </span>
                      <h3 className="text-h2 mt-2 text-ink md:mt-3">{d.name}</h3>
                      <p className="text-body mt-3 max-w-[46ch] text-ink-body md:text-body-lg md:mt-4">
                        {d.blurb}
                      </p>
                      {/* mt-4 rather than mt-7 below md. The pills are the
                          last thing in the column, so every pixel above
                          them is a pixel of the bottom row pushed under
                          the stage floor. */}
                      <ul className="mt-4 flex flex-wrap gap-2 md:mt-7">
                        {d.services.map((s) => (
                          <li key={s.slug}>
                            <Link
                              /* Was /services/<capability>, one page per
                                 pill. There are five pages now, one per
                                 discipline, so the pill points at THIS
                                 discipline's page with its own capability
                                 pre-opened - ServicePills reads the hash
                                 on mount. The pill still lands on the
                                 thing it names, which a bare link to the
                                 discipline page would have lost. */
                              href={`/services/${d.id}#${s.slug}`}
                              className="text-sm inline-block rounded-full border px-3.5 py-1.5 text-ink-body transition-colors duration-[var(--dur-fast)] hover:text-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-corporate-ink"
                              style={{
                                borderColor: `color-mix(in oklab, ${d.color} 45%, transparent)`,
                              }}
                              tabIndex={isActive ? 0 : -1}
                            >
                              {s.name}
                            </Link>
                          </li>
                        ))}
                      </ul>
                    </div>
                  );
                })}

                <div
                  aria-hidden={beat !== 6}
                  className="col-start-1 row-start-1 transition-[opacity,transform] ease-out-expo"
                  style={{
                    opacity: beat === 6 ? 1 : 0,
                    // The close only ever arrives from below; there is no
                    // beat after it to leave upward for.
                    transform: beat === 6 ? "none" : "translateY(18px)",
                    transitionDuration: beat === 6 ? "620ms" : "360ms",
                    transitionDelay: beat === 6 ? "110ms" : "0ms",
                    pointerEvents: beat === 6 ? "auto" : "none",
                  }}
                >
                  {/*
                    COUNTED, not written out. This read "Sixteen services"
                    for as long as there were sixteen, and stayed reading
                    it for a while after the list was replaced - the exact
                    failure the Footer's contact-details comment describes,
                    a number living in two files where only one of them
                    gets updated. A numeral in a display face is no worse
                    than the word, and this one cannot go stale.
                  */}
                  <h3 className="text-h2 max-w-[16ch] text-ink">
                    {SERVICES.length} services. One accountable team.
                  </h3>
                  <p className="text-body-lg mt-4 max-w-[46ch] text-ink-body">
                    Every figure in the mark is a discipline we run in-house,
                    which is why a brief never has to be handed between
                    agencies halfway through.
                  </p>
                  <div className="mt-8 flex flex-wrap gap-4">
                    <Link
                      href="/services"
                      // display:none used to take these out of the tab
                      // order for free; stacked and merely transparent,
                      // they would otherwise be focusable while invisible
                      // AND aria-hidden, which is the worst of both.
                      tabIndex={beat === 6 ? 0 : -1}
                      className="rounded-md bg-corporate-fill px-6 py-3 font-medium text-white transition-colors duration-[var(--dur-fast)] hover:bg-corporate-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-corporate-ink"
                    >
                      View All Services
                    </Link>
                    <HashLink
                      // Was /client-query, which no longer exists as a
                      // concept anywhere on the site - the nav collapsed
                      // its Contact menu and corner button into one
                      // Enquiry anchor. This button already said "Start an
                      // Enquiry"; now it goes to the form of that name.
                      // HashLink for the reason spelled out on "Explore
                      // Our Work" in act 1.
                      href="/#enquiry"
                      tabIndex={beat === 6 ? 0 : -1}
                      className="rounded-md border border-hairline px-6 py-3 font-medium text-ink transition-colors duration-[var(--dur-fast)] hover:border-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-corporate-ink"
                    >
                      Start an Enquiry
                    </HashLink>
                  </div>
                </div>
              </div>
            </div>

            {/*
              pointer-events-none, and it is the same trap the pinwheel
              layer above already fell into once - an aria-hidden decoration
              that is invisible to the eye but not to hit-testing.

              This strip is inset-x-0, so its box is the FULL WIDTH of the
              stage even though the dots themselves are a 100px cluster in
              the middle. On a phone the pill list now reaches down into
              that band: measured at 360x667 on Corporate & MICE, the widest
              list, elementFromPoint at the centre of the last row returned
              this div rather than the link, so the bottom third of "Travel"
              and "Logistics" was simply dead to a thumb. Nothing here is
              interactive - the dots are spans that report which beat you
              are on - so there is no reason for the strip to take a tap
              from anything underneath it.
            */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-0 bottom-6 flex justify-center gap-2 transition-opacity duration-[900ms] motion-reduce:hidden"
              style={{ opacity: entered ? 1 : 0 }}
            >
              {DISCIPLINES.map((d, i) => (
                <span
                  key={d.id}
                  className="h-1.5 rounded-full transition-all duration-[var(--dur-base)]"
                  style={{
                    width: beat === i + 1 ? 28 : 10,
                    background: i < beat ? d.color : "var(--color-hairline)",
                  }}
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function Thread({
  thread,
  front,
  gather,
}: {
  thread: (typeof THREADS)[number];
  front: MotionValue<number>;
  gather: MotionValue<number>;
}) {
  // Each thread trails the wipe front by its own lag, so the leading edge
  // reads as a braid rather than one hard line. On gather they converge on
  // 50% and their lengths collapse to nothing.
  const leftPct = useTransform([front, gather], ([f, g]: number[]) => {
    const lagged = Math.max(0, f - thread.lag * 100);
    return lagged + (50 - lagged) * g;
  });
  const widthPct = useTransform(gather, [0, 1], [thread.len * 100, 0]);
  const left = useMotionTemplate`${leftPct}%`;
  const width = useMotionTemplate`${widthPct}%`;

  const ref = useRef<HTMLSpanElement>(null);
  useMotionStyles(ref, { left, width });

  return (
    <span
      ref={ref}
      className="absolute h-[6px] -translate-x-full rounded-full"
      style={{
        top: `calc(50% + ${thread.y * 100}%)`,
        left: 0,
        width: 0,
        background: thread.color,
      }}
    />
  );
}
